
/**
 * CHAPTER 7 — STEP 3: GROUNDING & EVIDENCE VERIFICATION
 *
 * NEW FILE
 *
 * PURPOSE:
 * Verify that quotations generated by an LLM are
 * supported by actual employee feedback.
 *
 * WHY DO WE NEED THIS?
 * In Chapter 6, Gemini sometimes produced quotations
 * without retrieving the original feedback.
 *
 * We should not trust the LLM simply because it
 * sounds confident or provides a source ID.
 *
 * This helper performs deterministic verification
 * using ordinary TypeScript.
 *
 * IMPORTANT:
 * This verifies quotations, not the truth of every
 * claim or summary generated by the LLM.
 */

/**
 * Represents a feedback record that the application
 * has retrieved and made available as evidence.
 *
 * We only require:
 * - id: uniquely identifies the feedback record.
 * - text: the feedback content used for verification.
 *
 * CHAPTER 7 — PRIVACY CONNECTION:
 * Evidence should contain the redacted text supplied
 * to Gemini, not the original sensitive information.
 */
export interface FeedbackEvidence {
  id: string;
  text: string;
}

/**
 * Represents a quotation that Gemini claims
 * comes from a particular feedback record.
 *
 * We will eventually ask Gemini to produce this
 * structured information rather than extracting
 * quotations from an arbitrary text response.
 */
export interface FeedbackQuote {
  sourceId: string;
  quote: string;
}

/**
 * Describes the result of verifying a quotation.
 *
 * A discriminated union allows TypeScript to distinguish
 * successful verification from a failure.
 *
 * On success:
 *   { valid: true }
 *
 * On failure:
 *   { valid: false, reason: "..." }
 *
 * This prevents callers from receiving a failure
 * without an explanation.
 */
export type QuoteVerificationResult =
  | { valid: true }
  | { valid: false; reason: string };

/**
 * CHAPTER 7 — NEW HELPER
 *
 * Normalises whitespace before comparing strings.
 *
 * WHY?
 * Gemini might format the same quotation differently.
 *
 * Example:
 * "My manager is supportive\nand helpful."
 *
 * becomes:
 * "My manager is supportive and helpful."
 *
 * The regular expression:
 * \s+ matches one or more whitespace characters.
 *
 * We replace them with a single space and remove
 * whitespace from the beginning and end.
 *
 * We deliberately do not change words or punctuation,
 * because that would weaken quotation verification.
 */
const normaliseWhitespace = (text: string): string => {
  return text.replace(/\s+/g, " ").trim();
};


/**
 * CHAPTER 7 — GROUNDING: PRACTICAL EXAMPLES
 *
 * Imagine searchFeedback returned these records:
 *
 * feedback-001:
 * "My manager is supportive and always listens to my concerns."
 *
 * feedback-002:
 * "Senior management rarely recognises the extra effort our team puts in."
 *
 *
 * ✅ PASS — Exact quotation and correct source
 *
 * sourceId: "feedback-001"
 * quote: "My manager is supportive and always listens to my concerns."
 *
 * WHY? The quotation exists in feedback-001.
 *
 *
 * ✅ PASS — Partial quotation
 *
 * sourceId: "feedback-001"
 * quote: "My manager is supportive"
 *
 * WHY? The quotation is a substring of feedback-001.
 *
 *
 * ✅ PASS — Different whitespace
 *
 * sourceId: "feedback-001"
 * quote: "My manager is supportive\nand always listens to my concerns."
 *
 * WHY? We normalise whitespace before comparing.
 *
 *
 * ❌ FAIL — Invented quotation
 *
 * sourceId: "feedback-001"
 * quote: "Everyone loves their manager."
 *
 * WHY? These words do not appear in feedback-001.
 *
 *
 * ❌ FAIL — Correct quotation, wrong source
 *
 * sourceId: "feedback-002"
 * quote: "My manager is supportive"
 *
 * WHY? The quotation exists in feedback-001,
 * but NOT in feedback-002.
 *
 *
 * ❌ FAIL — Invented source ID
 *
 * sourceId: "feedback-999"
 * quote: "My manager is supportive"
 *
 * WHY? feedback-999 was never retrieved.
 *
 *
 * ❌ FAIL — Paraphrasing instead of quoting
 *
 * sourceId: "feedback-001"
 * quote: "My manager always supports me."
 *
 * WHY? This conveys a similar meaning, but the
 * exact words are not present in the source.
 *
 * IMPORTANT LIMITATION:
 *
 * This function verifies literal quotations only.
 * It cannot determine whether summaries, paraphrases
 * or conclusions are factually supported.
 *
 * For example:
 *
 * "All employees are happy with management."
 *
 * Our current verifier cannot assess this statement
 * because it is not represented as a source-linked
 * quotation.
 *
 * That is why we'll introduce structured answers
 * and additional grounding checks next.
 */

export const verifyFeedbackQuote = (
  quotation: FeedbackQuote,
  evidence: FeedbackEvidence[],
): QuoteVerificationResult => {
  /**
   * STEP 1 — FIND THE CLAIMED SOURCE
   *
   * Array.find() returns the first matching record,
   * or undefined if no matching record exists.
   *
   * We must check the specific source ID rather than
   * searching all feedback records indiscriminately.
   */
  const source = evidence.find(
    (item) => item.id === quotation.sourceId,
  );

  /**
   * STEP 2 — REJECT UNKNOWN SOURCES
   *
   * An LLM could invent a plausible-looking ID.
   * We only accept IDs present in retrieved evidence.
   */
  if (!source) {
    return {
      valid: false,
      reason: `Unknown source ID: ${quotation.sourceId}`,
    };
  }

  /**
   * STEP 3 — NORMALISE TEXT
   *
   * This avoids false mismatches caused by line breaks
   * or repeated spaces.
   */
  const quote = normaliseWhitespace(quotation.quote);
  const sourceText = normaliseWhitespace(source.text);

  /**
   * STEP 4 — REJECT EMPTY QUOTATIONS
   *
   * JavaScript considers an empty string to be
   * contained in every string:
   *
   * "hello".includes("") === true
   *
   * Without this check, empty quotations would pass.
   */
  if (!quote) {
    return {
      valid: false,
      reason: "Quotation is empty.",
    };
  }

  /**
   * STEP 5 — VERIFY THE QUOTATION
   *
   * String.includes() checks whether the quotation
   * exists within the source text.
   *
   * This is deliberately stricter than asking
   * another LLM whether a quotation looks correct.
   */
  if (!sourceText.includes(quote)) {
    return {
      valid: false,
      reason:
        `Quotation does not match source: ${quotation.sourceId}`,
    };
  }

  /**
   * STEP 6 — RETURN SUCCESS
   *
   * Both the source and quotation have been verified.
   */
  return {
    valid: true,
  };
};
